import Image from "next/image";
import { cn } from "@/lib/cn";
import { BRAND } from "@/lib/brand";
import { BRAND_ASSETS } from "@/lib/brandAssets";

const { logoHorizontal, logoMark } = BRAND_ASSETS;

// Rendered sizes (CSS px) of the horizontal logo; width follows its aspect ratio.
const RATIO = logoHorizontal.width / logoHorizontal.height;
const HEADER_H = 32;
const FOOTER_H = 36;

/**
 * CampusEduX logo (mark + wordmark, generated by scripts/generate-logos.mjs), shared by the
 * header and footer. The navy wordmark is unreadable on the dark card, so in dark mode the logo
 * sits on a white rounded pill instead of being recoloured.
 * `compact` (header): below `sm` the logo is a little smaller (no wider than the old tile +
 * wordmark), and below 360px only the CX mark shows, so the header's actions always fit the
 * phone width. The header link carries the accessible name; the footer logo keeps its alt.
 */
export function BrandMark({ className, compact = false }: { className?: string; compact?: boolean }) {
  const height = compact ? HEADER_H : FOOTER_H;
  return (
    <span
      className={cn(
        "flex items-center dark:rounded-lg dark:bg-white",
        compact ? "dark:px-1 dark:py-0.5 sm:dark:px-1.5 sm:dark:py-1" : "dark:px-2 dark:py-1",
        className,
      )}
    >
      <Image
        src={logoHorizontal.src}
        alt={BRAND.name}
        width={Math.round(height * RATIO)}
        height={height}
        priority={compact}
        className={cn("w-auto", compact ? "h-7 max-[359px]:hidden sm:h-8" : "h-9")}
      />
      {compact ? (
        <Image src={logoMark.src} alt={BRAND.name} width={32} height={32} className="hidden h-8 w-8 max-[359px]:block" />
      ) : null}
    </span>
  );
}

export default BrandMark;
